import math

def paginate(items: list, page: int, per_page: int) -> dict:
    total = len(items)
    if per_page <= 0:
        total_pages = 0
        page_items = []
    else:
        total_pages = math.ceil(total / per_page)
        if page < 1:
            page_items = []
        else:
            start = (page - 1) * per_page
            page_items = items[start:start + per_page]
    return {'items': page_items, 'page': page, 'total_pages': total_pages}
```
Note: handled per_page<=0 and page<1 to avoid div0/crash/wrong slices (unsure if problem expects this vs. assume valid inputs only).

